-- =============================================================================
-- ⚠️ 本文件已作废（2026-08-07），请勿执行
-- 原因：其中的期货交易手续费数据仍处于待核验状态，暂不采用。
--       两列 futures_trading_fee / futures_fee_source 已由
--       03_drop_futures_trading_fee.sql 从 public.symbol 表中删除。
-- 保留本文件仅作历史记录；若日后费率核验通过，请核对后再决定是否重新启用。
-- =============================================================================

-- 来源：各交易所官网官方一手费率表（详见各行 futures_fee_source）
-- 含义：symbol 表新增 futures_trading_fee（期货交易手续费，文本）与 futures_fee_source（官方来源URL）
-- 范围：仅期货品种；期权品种（含 CFFEX 的 HO/IO/MO 股指期权）不填，保持 NULL
-- 口径：交易所向会员收取的开仓/平仓期货交易费；不含期货公司加收、申报费、交割/行权费
-- 执行：psql "$DATABASE_URL" -f 02_add_futures_trading_fee.sql

ALTER TABLE public.symbol ADD COLUMN IF NOT EXISTS futures_trading_fee TEXT;
ALTER TABLE public.symbol ADD COLUMN IF NOT EXISTS futures_fee_source TEXT;
COMMENT ON COLUMN public.symbol.futures_trading_fee IS '期货交易手续费（交易所开平仓费，官方一手数据）；不含期权/交割费';
COMMENT ON COLUMN public.symbol.futures_fee_source IS '期货交易手续费官方一手来源URL';

-- 数据校正：伦镍/伦铜/伦铝/伦铅/伦锡 原误标为 HKEX（实为 HKEX 伦敦金属迷你期货），
-- 按用户数据口径应归属 LME（与伦锌 ZS 一致）。此处将交易所更正为 LME（幂等，重跑安全）。
UPDATE public.symbol SET exchange_code = 'LME'
WHERE exchange_code = 'HKEX' AND symbol_code IN ('NI','CA','AH','PB','SN');

